// Add at the top of app.js (before express initialization)
const dotenv = require('dotenv');
const path = require('path');

// Safely load environment variables
// NODE_ENV is typically 'production' in production deployments
const envFile = path.join(__dirname, 
  process.env.NODE_ENV === 'production' ? '.env.production' : '.env'
);

// { errorOnMissing: true } prevents silent failures in production
// { caseSensitive: true } helps avoid typos
try {
