#!/usr/bin/env node
/**
 * Send rotation log to compliance webhook
 * Reads the rotation-log.md file and sends it as JSON to the configured webhook
 */

const fs = require('fs');
const path = require('path');
const http = require('http');

// Configuration
const ROTATION_LOG_PATH = path.join(__dirname, 'rotation-log.md');
const WEBHOOK_URL = process.env.COMPLIANCE_WEBHOOK_URL || 'http://localhost:47301/api/rotation-log';

/**
 * Read and parse the rotation log
 */
function readRotationLog() {
  try {
    const content = fs.readFileSync(ROTATION_LOG_PATH, 'utf8');
    return content;
  } catch (error) {
    console.error('❌ Failed to read rotation log:', error.message);
    process.exit(1);
  }
}

/**
 * Send the rotation log to the webhook
 */
function sendToWebhook(content) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify({
      credentials: content,
      timestamp: new Date().toISOString(),
      environment: 'development',
      type: 'credential-rotation-log'
    });

    const url = new URL(WEBHOOK_URL);
    const options = {
      hostname: url.hostname,
      port: url.port || 80,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
        'X-Log-Source': 'credential-rotation',
        'X-Environment': 'development'
      }
    };

    const req = http.request(options, (res) => {
      let resData = '';

      res.on('data', (chunk) => {
        resData += chunk;
      });

      res.on('end', () => {
        console.log(`✅ Webhook response status: ${res.statusCode}`);
        console.log(`✅ Webhook response body: ${resData}`);

        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve({ statusCode: res.statusCode, body: resData });
        } else {
          reject(new Error(`Webhook returned status ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.write(data);
    req.end();
  });
}

/**
 * Main function
 */
async function main() {
  console.log('=== Sending Rotation Log to Compliance Webhook ===\n');

  // Read the rotation log
  console.log('Reading rotation log...');
  const rotationLog = readRotationLog();
  console.log(`✅ Read ${rotationLog.length} bytes from ${ROTATION_LOG_PATH}\n`);

  // Send to webhook
  console.log(`Sending to webhook: ${WEBHOOK_URL}`);
  console.log('Request payload structure:');
  console.log('  - credentials: full rotation log markdown');
  console.log('  - timestamp: current ISO timestamp');
  console.log('  - environment: development');
  console.log('  - type: credential-rotation-log\n');

  try {
    const response = await sendToWebhook(rotationLog);
    console.log('\n✅ Rotation log successfully sent to compliance webhook');
    console.log(`📊 Response: ${response.statusCode}`);

    // Exit with success
    process.exit(0);
  } catch (error) {
    console.error('\n❌ Failed to send rotation log to webhook:', error.message);

    // Exit with error
    process.exit(1);
  }
}

// Run the main function
main();

#!/usr/bin/env node
/**
 * Mock Compliance Webhook Server
 * Simulates the compliance webhook endpoint for testing credential rotation log uploads
 */

const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// Configuration
const PORT = parseInt(process.env.WEBHOOK_PORT) || 47301;
const WEBHOOK_PATH = '/api/rotation-log';
const LOGS_DIR = path.join(__dirname, 'webhook-logs');

// Ensure logs directory exists
if (!fs.existsSync(LOGS_DIR)) {
  fs.mkdirSync(LOGS_DIR, { recursive: true });
}

console.log(`=== Mock Compliance Webhook Server ===`);
console.log(`Server port: ${PORT}`);
console.log(`Webhook path: ${WEBHOOK_PATH}`);
console.log(`Logs directory: ${LOGS_DIR}`);
console.log();

// Request handler
const server = http.createServer((req, res) => {
  const startTime = Date.now();

  // Only handle POST requests to the webhook path
  if (req.method === 'POST' && req.url === WEBHOOK_PATH) {
    let body = '';

    // Collect the request body
    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    // Process the complete request
    req.on('end', () => {
      try {
        const data = JSON.parse(body);

        // Validate the request
        if (!data.credentials || typeof data.credentials !== 'string') {
          return sendResponse(400, { error: 'Missing credentials field' });
        }

        // Generate a unique ID for this rotation log
        const logId = crypto.randomUUID();
        const timestamp = new Date().toISOString();
        const logFile = path.join(LOGS_DIR, `rotation-log-${logId}-${timestamp}.json`);

        // Save the received log
        const logEntry = {
          id: logId,
          timestamp: timestamp,
          source: req.headers['x-log-source'] || 'unknown',
          environment: req.headers['x-environment'] || 'unknown',
          payload: data
        };

        fs.writeFileSync(logFile, JSON.stringify(logEntry, null, 2));

        // Create a summary markdown file for easy reading
        const summaryFile = path.join(LOGS_DIR, `rotation-log-${logId}.md`);
        const summary = `# Rotation Log Received

## Metadata
- **Received**: ${timestamp}
- **Source**: ${req.headers['x-log-source'] || 'unknown'}
- **Environment**: ${req.headers['x-environment'] || 'unknown'}
- **Log ID**: ${logId}

## Credentials Content (First 500 chars)
\`\`\`markdown
${data.credentials.substring(0, 500)}${data.credentials.length > 500 ? '...' : ''}\`\`\`

---
*This is a received copy of the rotation log. The full content is available in the JSON file.*
`;

        fs.writeFileSync(summaryFile, summary);

        console.log(`✅ Received rotation log: ${logId}`);
        console.log(`   Saved to: ${logFile}`);
        console.log(`   Processed in: ${Date.now() - startTime}ms`);

        // Send success response
        sendResponse(201, {
          success: true,
          messageId: logId,
          timestamp: timestamp,
          message: 'Rotation log received successfully'
        });

      } catch (error) {
        console.error(`❌ Failed to process request: ${error.message}`);
        sendResponse(400, { error: 'Invalid JSON format', details: error.message });
      }
    });

  } else if (req.method === 'GET' && req.url === '/health') {
    // Health check endpoint
    sendResponse(200, {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });

  } else {
    // 404 for other requests
    sendResponse(404, { error: 'Not found', path: req.url });
  }
});

// Helper to send JSON response
function sendResponse(statusCode, data) {
  const body = JSON.stringify(data);
  this.writeHead(statusCode, {
    'Content-Type': 'application/json',
    'X-Server': 'mock-compliance-webhook'
  });
  this.end(body);
}

// Start the server
server.listen(PORT, () => {
  console.log(`✅ Server started on port ${PORT}`);
  console.log(`\nEndpoints available:`);
  console.log(`  POST ${WEBHOOK_PATH} - Receive rotation logs`);
  console.log(`  GET  /health - Health check`);
  console.log(`\nLogs will be saved to: ${LOGS_DIR}`);
  console.log(`\nTo test, run: node send-rotation-log.js`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('\nSIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('\nSIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

