  message: err.message,
  stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined,
  type: err.constructor.name,
});
```

**Recommendation**: Sanitize all logged data and ensure stack traces are never exposed in production.

**Improved Implementation**:
```javascript
const logger = require('pino')({
  level: process.env.NODE_ENV === 'production' ? 'info' : 'debug',
  transport: {
    target: 'pino-pretty',
    options: {
      translateTime: true,
      ignore: 'pid,hostname',
    },
  },
});

const errorHandler = (err, req, res, next) => {
  // Sanitize data before logging
  const sanitizedError = {
    message: err.message,
    type: err.constructor.name,
    stack: process.env.NODE_ENV !== 'production' 
      && process.env.DEBUG === 'true' 
      ? err.stack 
      : undefined,
    endpoint: req.path,
    method: req.method,
    ip: req.ip,
    userId: req.user?.id || null, // Redact personal info in production
  };

  // Only log stack traces if explicitly enabled and not in production
  if (process.env.NODE_ENV !== 'production' && process.env.DEBUG === 'true') {
    logger.error(sanitizedError);
  } else {
    logger.warn({
      ...sanitizedError,
      stack: undefined
    });
  }

  // Send generic error to client (already implemented correctly)
  res.status(err.status || 500).json({
    error: err.status === 429 ? err.message : 'Internal server error',
  });
};
