### Option 2: AWS Secrets Manager (Recommended for AWS)
If deploying to AWS, use Secrets Manager with IAM roles.

**Implementation**:
```javascript
// secrets-manager.js
import { SecretsManagerClient, GetSecretValueCommand } from '@aws-sdk/client-secrets-manager';

const client = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1',
});

export async function getSecret(secretName) {
  try {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await client.send(command);

    if (response.SecretString) {
      const secret = JSON.parse(response.SecretString);
      return secret;
    }

    if (response.SecretBinary) {
      return JSON.parse(Buffer.from(response.SecretBinary).toString('utf8'));
    }

    throw new Error('Secret value not found');
  } catch (error) {
    console.error(`Failed to get secret ${secretName}:`, error.message);
    throw error;
  }
}

// Usage in your app
// const { DATABASE_URL } = await getSecret('myapp/production/database');
```

### Option 3: HashiCorp Vault (Universal Solution)
For on-premises or multi-cloud deployments, use HashiCorp Vault.

**Implementation**:
