  apiVersion: 'v1',
  endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
  token: process.env.VAULT_TOKEN,
});

export async function getSecret(path) {
  try {
    const secret = await vault.read(path);
    return secret.data;
  } catch (error) {
    console.error(`Vault secret ${path} not found:`, error.message);
    throw error;
  }
}

