/**
 * OpenAI Client — minimal chat-completions wrapper.
 *
 * Used by PromptArmorBaseline (and any future OpenAI-backed feature) for
 * single-call detector-style requests: system prompt + one user message,
 * no tools, no streaming, deterministic temperature. Mirrors the
 * shape of bedrock-client.ts so callers can swap backends with the
 * same surface.
 *
 * Uses the global fetch (Node 22+) to avoid adding the openai SDK as
 * a runtime dependency. The chat-completions API surface is stable
 * enough for this.
 *
 * Caller responsibilities:
 *   - Set OPENAI_API_KEY in env. We do not read this at module load
 *     so the absence is a per-call failure rather than a startup crash.
 *   - Pick the model. We don't map friendly aliases here (executor-
 *     openai.ts has a MODEL_MAP for that — caller-side concern).
 */

interface OpenAIChatResponse {
  choices: Array<{
    message: { content: string | null };
    finish_reason: string;
  }>;
  usage: {
    prompt_tokens: number;
    completion_tokens: number;
    total_tokens: number;
  };
}

export interface OpenAIChatResult {
  content: string;
  durationMs: number;
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
  finishReason: string;
}

export async function openaiChat(
  systemPrompt: string,
  userMessage: string,
  modelId: string,
  opts: {
    /** Defaults to 0 for deterministic detector-style use. */
    temperature?: number;
    /** Cap on output tokens. */
    maxTokens?: number;
    /** Per-call abort timeout in ms; default 60s. */
    timeoutMs?: number;
  } = {},
): Promise<OpenAIChatResult> {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) {
    throw new Error("OPENAI_API_KEY not set");
  }

  const body = {
    model: modelId,
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: userMessage },
    ],
    temperature: opts.temperature ?? 0,
    max_tokens: opts.maxTokens ?? 256,
  };

  const start = Date.now();
  const maxAttempts = 3;
  let lastErr: Error | null = null;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const res = await fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${apiKey}`,
        },
        body: JSON.stringify(body),
        signal: AbortSignal.timeout(opts.timeoutMs ?? 60_000),
      });

      if (!res.ok) {
        const text = await res.text().catch(() => "");
        if ((res.status === 429 || res.status >= 500) && attempt < maxAttempts) {
          const backoff = 1000 * Math.pow(2, attempt - 1);
          console.warn(
            `  [openai ${res.status}] attempt ${attempt}/${maxAttempts}; sleeping ${backoff}ms`,
          );
          await new Promise((r) => setTimeout(r, backoff));
          continue;
        }
        throw new Error(`OpenAI HTTP ${res.status}: ${text.substring(0, 500)}`);
      }

      const json = (await res.json()) as OpenAIChatResponse;
      const choice = json.choices?.[0];
      const content = choice?.message?.content ?? "";
      const usage = json.usage ?? { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 };
      return {
        content,
        durationMs: Date.now() - start,
        inputTokens: usage.prompt_tokens,
        outputTokens: usage.completion_tokens,
        totalTokens: usage.total_tokens,
        finishReason: choice?.finish_reason ?? "unknown",
      };
    } catch (err) {
      lastErr = err instanceof Error ? err : new Error(String(err));
      if (attempt < maxAttempts) {
        const backoff = 1000 * Math.pow(2, attempt - 1);
        console.warn(
          `  [openai fetch] attempt ${attempt}/${maxAttempts}: ${lastErr.message}; sleeping ${backoff}ms`,
        );
        await new Promise((r) => setTimeout(r, backoff));
        continue;
      }
    }
  }
  throw lastErr ?? new Error("OpenAI call failed with no captured error");
}

/**
 * Ollama Client
 *
 * Lightweight HTTP client for Ollama's local API.
 * Provides embedding generation and chat completion
 * without any external dependencies.
 */

const OLLAMA_BASE = process.env.OLLAMA_HOST ?? "http://localhost:11434";

export interface EmbeddingResponse {
  embeddings: number[][];
}

export interface ChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
  /** Base64-encoded images (Ollama vision models only) */
  images?: string[];
}

export interface ChatResponse {
  message: {
    role: string;
    content: string;
  };
  total_duration?: number;
  eval_count?: number;
}

/**
 * Generate embeddings for one or more texts.
 */
export async function embed(
  texts: string | string[],
  model = "nomic-embed-text"
): Promise<number[][]> {
  const input = Array.isArray(texts) ? texts : [texts];

  const res = await fetch(`${OLLAMA_BASE}/api/embed`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model, input }),
  });

  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Ollama embed failed (${res.status}): ${body}`);
  }

  const data = (await res.json()) as EmbeddingResponse;
  return data.embeddings;
}

/**
 * Chat completion with a local model. Streaming disabled for simplicity.
 */
export async function chat(
  messages: ChatMessage[],
  model = "llama3.2"
): Promise<{ content: string; durationMs: number }> {
  const start = Date.now();

  const res = await fetch(`${OLLAMA_BASE}/api/chat`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model, messages, stream: false }),
  });

  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Ollama chat failed (${res.status}): ${body}`);
  }

  const data = (await res.json()) as ChatResponse;
  return {
    content: data.message.content,
    durationMs: Date.now() - start,
  };
}

/**
 * Route an embed call to Bedrock or Ollama based on the model name.
 * Bedrock model IDs start with a known provider prefix (with or without a
 * region qualifier like eu./us./global.). Ollama model names never do.
 */
const BEDROCK_PREFIXES = /^(?:eu\.|us\.|global\.|amazon\.|cohere\.|twelvelabs\.|anthropic\.|meta\.|mistral\.|nvidia\.)/;

export function isBedrockModel(model: string): boolean {
  return BEDROCK_PREFIXES.test(model);
}

export async function embedAny(
  texts: string | string[],
  model: string
): Promise<number[][]> {
  if (isBedrockModel(model)) {
    const { bedrockEmbed } = await import("./bedrock-client.js");
    const arr = Array.isArray(texts) ? texts : [texts];
    return bedrockEmbed(arr, model);
  }
  return embed(texts, model);
}

/**
 * Cosine similarity between two vectors.
 */
export function cosineSimilarity(a: number[], b: number[]): number {
  if (a.length !== b.length) {
    throw new Error(`Vector dimension mismatch: ${a.length} vs ${b.length}`);
  }
  let dot = 0;
  let normA = 0;
  let normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  const denom = Math.sqrt(normA) * Math.sqrt(normB);
  return denom === 0 ? 0 : dot / denom;
}

/**
 * Check if Ollama is reachable and the required models are available.
 */
export async function checkOllama(
  embeddingModel: string,
  chatModel?: string
): Promise<{ ok: boolean; missing: string[] }> {
  const required = chatModel ? [embeddingModel, chatModel] : [embeddingModel];
  try {
    const res = await fetch(`${OLLAMA_BASE}/api/tags`);
    if (!res.ok) return { ok: false, missing: required };

    const data = (await res.json()) as { models: { name: string }[] };
    const available = new Set(data.models.map((m) => m.name.split(":")[0]));

    const missing: string[] = [];
    for (const m of required) {
      if (!available.has(m.split(":")[0])) missing.push(m);
    }

    return { ok: missing.length === 0, missing };
  } catch {
    return { ok: false, missing: required };
  }
}

/**
 * Approval store.
 *
 * "Learning" layer for interactive-mode trust. When Dredd asks the user
 * about a tool call and the user accepts, we record the fingerprint of
 * that tool call against (ownerSub, projectRoot). The next time the
 * same fingerprint appears we short-circuit the three-stage pipeline
 * and auto-allow — saving the user from re-consenting to the same
 * action over and over.
 *
 * Three implementations, same interface (mirrors `ApiKeyStore`):
 *   - `InMemoryApprovalStore` — process-local Map, for local dev.
 *   - `DynamoApprovalStore`   — durable storage in `jaid-approvals`.
 *   - `CachedApprovalStore`   — write-through LRU wrapper.
 *
 * Scope: per-Clerk-userId AND per-projectRoot. Approvals don't cross
 * users (ownerSub) and don't cross projects (an approval granted while
 * working in ~/foo doesn't fire in ~/bar). Across sessions within that
 * scope, yes — that's the whole point.
 *
 * Safety invariants:
 *   - Raw secrets are NEVER stored. The curl fingerprinter hashes the
 *     Authorization token before it ever reaches this layer.
 *   - Hard policy denies (DENIED_BASH_PATTERNS, dangerous combos) and
 *     hijack-locked sessions are checked BEFORE the approval lookup —
 *     no approval can override the safety floor.
 *   - Intent drift snapshotted at approval time; lookups reject if the
 *     session has drifted far from the original consenting intent.
 */

// ---- types -----------------------------------------------------------------

/** Composite scope: same user, same project. */
export interface ApprovalScope {
  ownerSub: string;
  projectRoot: string;
}

/** What we persist per approval. */
export interface ApprovalRecord {
  /** sha256(stable-JSON(fingerprint shape)) — primary identifier within scope. */
  fingerprintHash: string;
  /** Human-readable one-liner for the dashboard, e.g.
   *  "curl to api.stripe.com with API key 4f3a…". Never contains secrets. */
  summary: string;
  /** Raw fingerprint JSON for audit/debugging. */
  fingerprintJson: string;
  /** Tool name, e.g. "Bash", "Edit", "WebFetch". */
  tool: string;

  ownerSub: string;
  ownerEmail: string | null;
  projectRoot: string;

  grantedAt: string;
  /** Refreshed on every hit; drives the 30-day TTL. */
  lastUsedAt: string;
  useCount: number;
  /** lastUsedAt + 30d, ISO. Dynamo TTL uses the epoch-seconds form. */
  expiresAt: string;

  /** User prompt active at approval time (for the dashboard's UI). */
  intentSnapshot: string;
  /** Goal embedding snapshot for the intent-drift backstop. Cosine
   *  distance > APPROVAL_INTENT_DRIFT_THRESHOLD at lookup time rejects
   *  the approval even though the fingerprint matches. */
  goalEmbedding: number[];
  /** Phase 8a — embedding of `tool + JSON(toolInput)` at consent time.
   *  Drives the pattern-trust learning in Phase 8b/c: similarity of the
   *  current /evaluate call against this vector decides whether the
   *  judge gets prior-approval context (soft) and whether enough
   *  similar prior approvals short-circuit the pipeline (hard).
   *  Empty array `[]` for legacy records written before this field
   *  existed — those rows fall through to the existing fingerprint
   *  match path. */
  inputEmbedding: number[];

  /** Set when revoked from the dashboard. Active records have null. */
  revokedAt: string | null;
  revokedBy: string | null;
}

/** Input to `recordApproval` — everything except server-set timestamps. */
export interface RecordApprovalInput {
  scope: ApprovalScope;
  ownerEmail: string | null;
  fingerprintHash: string;
  fingerprintJson: string;
  summary: string;
  tool: string;
  intentSnapshot: string;
  goalEmbedding: number[];
  /** Phase 8a — see ApprovalRecord.inputEmbedding. Callers compute
   *  this via embedAny(JSON({tool,input})) just before recordApproval.
   *  Pass [] if the embed call failed; the row is still persisted but
   *  won't contribute to pattern-trust matching. */
  inputEmbedding: number[];
}

export interface ApprovalStore {
  /** Persist an approval. The PostToolUse arrival is our trigger to
   *  promote a pending in-memory candidate to a durable record. If a
   *  record with the same (scope, fingerprintHash) already exists,
   *  refreshes its lastUsedAt/expiresAt and increments useCount. */
  recordApproval(input: RecordApprovalInput): Promise<ApprovalRecord>;

  /** Look up by (scope, fingerprintHash). Returns null when no live
   *  record exists (missing or revoked). Pure read — does NOT bump
   *  lastUsedAt; use `touchLastUsed` for that, called after the
   *  intent-drift check passes. */
  lookup(scope: ApprovalScope, fingerprintHash: string): Promise<ApprovalRecord | null>;

  /** Side-effect call after a successful approval-allow: bump useCount,
   *  refresh lastUsedAt + expiresAt. Fire-and-forget from callers. */
  touchLastUsed(scope: ApprovalScope, fingerprintHash: string): Promise<void>;

  /** Dashboard listing — newest first, excludes revoked. */
  listByOwner(ownerSub: string, limit?: number): Promise<ApprovalRecord[]>;

  /** Admin listing — every owner. Best-effort ordering. */
  listAll(limit?: number): Promise<ApprovalRecord[]>;

  /** Phase 8a — list every LIVE (non-revoked, non-expired) approval
   *  for one (ownerSub, projectRoot). Hot path: called on every
   *  /evaluate that has pattern-trust enabled to compute embedding
   *  similarity against the incoming tool call. Implementations must
   *  exclude revoked rows. limit defaults to 200 — well above the
   *  expected steady-state of approvals per project. */
  listForScope(scope: ApprovalScope, limit?: number): Promise<ApprovalRecord[]>;

  /** Soft-revoke. Sets revokedAt/revokedBy; returns true if a live
   *  record was found and revoked, false otherwise. */
  revoke(scope: ApprovalScope, fingerprintHash: string, revokedBy: string): Promise<boolean>;
}

// ---- in-memory implementation ---------------------------------------------

/** Composite key for the in-memory Map. */
function recordKey(scope: ApprovalScope, fingerprintHash: string): string {
  return `${scope.ownerSub}|${scope.projectRoot}|${fingerprintHash}`;
}

/** 30 days in milliseconds — the TTL window for an approval. Refreshed
 *  on every hit, so an approval used weekly stays alive indefinitely. */
export const APPROVAL_TTL_MS = 30 * 24 * 60 * 60 * 1000;

/** Cosine-distance threshold above which a session's current intent is
 *  considered too far from the original approving intent. Set high
 *  enough that legitimate clarifications don't invalidate but low
 *  enough that a goal pivot does. Tune in production. */
export const APPROVAL_INTENT_DRIFT_THRESHOLD = 0.4;

export class InMemoryApprovalStore implements ApprovalStore {
  private records = new Map<string, ApprovalRecord>();

  async recordApproval(input: RecordApprovalInput): Promise<ApprovalRecord> {
    const key = recordKey(input.scope, input.fingerprintHash);
    const now = new Date().toISOString();
    const expiresAt = new Date(Date.now() + APPROVAL_TTL_MS).toISOString();

    const existing = this.records.get(key);
    if (existing && !existing.revokedAt) {
      existing.lastUsedAt = now;
      existing.useCount += 1;
      existing.expiresAt = expiresAt;
      return existing;
    }

    const record: ApprovalRecord = {
      fingerprintHash: input.fingerprintHash,
      summary: input.summary,
      fingerprintJson: input.fingerprintJson,
      tool: input.tool,
      ownerSub: input.scope.ownerSub,
      ownerEmail: input.ownerEmail,
      projectRoot: input.scope.projectRoot,
      grantedAt: now,
      lastUsedAt: now,
      useCount: 1,
      expiresAt,
      intentSnapshot: input.intentSnapshot,
      goalEmbedding: input.goalEmbedding,
      inputEmbedding: input.inputEmbedding ?? [],
      revokedAt: null,
      revokedBy: null,
    };
    this.records.set(key, record);
    return record;
  }

  async lookup(scope: ApprovalScope, fingerprintHash: string): Promise<ApprovalRecord | null> {
    const record = this.records.get(recordKey(scope, fingerprintHash));
    if (!record) return null;
    if (record.revokedAt) return null;
    if (new Date(record.expiresAt).getTime() < Date.now()) return null;
    return record;
  }

  async touchLastUsed(scope: ApprovalScope, fingerprintHash: string): Promise<void> {
    const record = this.records.get(recordKey(scope, fingerprintHash));
    if (!record || record.revokedAt) return;
    record.lastUsedAt = new Date().toISOString();
    record.useCount += 1;
    record.expiresAt = new Date(Date.now() + APPROVAL_TTL_MS).toISOString();
  }

  async listByOwner(ownerSub: string, limit = 200): Promise<ApprovalRecord[]> {
    const out: ApprovalRecord[] = [];
    for (const r of this.records.values()) {
      if (r.ownerSub !== ownerSub) continue;
      if (r.revokedAt) continue;
      out.push(r);
    }
    out.sort((a, b) => b.grantedAt.localeCompare(a.grantedAt));
    return out.slice(0, limit);
  }

  async listAll(limit = 500): Promise<ApprovalRecord[]> {
    const out: ApprovalRecord[] = [];
    for (const r of this.records.values()) {
      if (r.revokedAt) continue;
      out.push(r);
    }
    out.sort((a, b) => b.grantedAt.localeCompare(a.grantedAt));
    return out.slice(0, limit);
  }

  async listForScope(scope: ApprovalScope, limit = 200): Promise<ApprovalRecord[]> {
    const now = Date.now();
    const out: ApprovalRecord[] = [];
    for (const r of this.records.values()) {
      if (r.ownerSub !== scope.ownerSub) continue;
      if (r.projectRoot !== scope.projectRoot) continue;
      if (r.revokedAt) continue;
      if (new Date(r.expiresAt).getTime() < now) continue;
      out.push(r);
    }
    out.sort((a, b) => b.grantedAt.localeCompare(a.grantedAt));
    return out.slice(0, limit);
  }

  async revoke(scope: ApprovalScope, fingerprintHash: string, revokedBy: string): Promise<boolean> {
    const record = this.records.get(recordKey(scope, fingerprintHash));
    if (!record || record.revokedAt) return false;

/**
 * DynamoDB-backed ApprovalStore.
 *
 * Persists user-granted approvals so the "learning" survives container
 * replacement, restart, and cross-session re-use. Sits behind
 * `CachedApprovalStore` — every PreToolUse asks "do we have an approval
 * for this fingerprint?", which would otherwise round-trip to Dynamo.
 *
 * Item shape (single table `jaid-approvals`):
 *
 *   pk           = APPROVAL#<ownerSub>#<projectRootHash16>
 *   sk           = FP#<fingerprintHash>
 *
 *   ownerSub     = OIDC sub claim
 *   ownerEmail   = OIDC email (display only)
 *   projectRoot  = absolute path of the Claude working directory
 *   tool         = "Bash" | "Edit" | "WebFetch" | "mcp__…"
 *   fingerprintHash
 *   fingerprintJson  = canonical JSON of the fingerprint shape
 *   summary      = human-readable description (no secrets)
 *
 *   grantedAt    = ISO-8601
 *   lastUsedAt   = ISO-8601               — refreshed on every hit
 *   useCount     = N                       — incremented on every hit
 *   expiresAt    = ISO-8601               — lastUsedAt + 30d
 *
 *   intentSnapshot  = user prompt at grant time (for the dashboard)
 *   goalEmbedding   = number[]              — drift-distance backstop
 *
 *   revokedAt?   = ISO-8601               — absent means active
 *   revokedBy?   = OIDC sub
 *
 *   gsi1pk       = USER#<ownerSub>        — present on active rows only
 *   gsi1sk       = APPROVAL#<grantedAt>#<fingerprintHash>
 *   ttl          = <epoch-seconds>         — same instant as expiresAt
 *
 * GSI1 is the cheap dashboard listing path (Query by USER#<sub>,
 * newest-first via ScanIndexForward=false). Revoked rows have GSI1
 * keys REMOVED so they drop out of the listing without a
 * FilterExpression — same pattern as jaid-api-keys.
 *
 * Injection-resistance invariants (do not break):
 *   - No PartiQL. Parameterised DocumentClient commands throughout.
 *   - ownerSub and fingerprintHash are derived (clerk-issued / sha256);
 *     projectRoot is sha256-truncated before it lands in the pk so a
 *     pathological path can't malform a key.
 */

import { DynamoDBClient } from "@aws-sdk/client-dynamodb";
import {
  DynamoDBDocumentClient,
  GetCommand,
  PutCommand,
  UpdateCommand,
  QueryCommand,
  ScanCommand,
} from "@aws-sdk/lib-dynamodb";
import { createHash } from "node:crypto";

import {
  type ApprovalStore,
  type ApprovalRecord,
  type ApprovalScope,
  type RecordApprovalInput,
  APPROVAL_TTL_MS,
} from "./approval-store.js";

export interface DynamoApprovalStoreOptions {
  tableName: string;
  region: string;
  /** Override for tests. */
  client?: DynamoDBDocumentClient;
}

const GSI_NAME = "gsi1";

function projectRootHash(path: string): string {
  return createHash("sha256").update(path).digest("hex").slice(0, 16);
}

function pk(scope: ApprovalScope): string {
  return `APPROVAL#${scope.ownerSub}#${projectRootHash(scope.projectRoot)}`;
}

function sk(fingerprintHash: string): string {
  return `FP#${fingerprintHash}`;
}

function userGsiPk(sub: string): string {
  return `USER#${sub}`;
}

function userGsiSk(grantedAt: string, fingerprintHash: string): string {
  return `APPROVAL#${grantedAt}#${fingerprintHash}`;
}

function nowEpochSec(): number {
  return Math.floor(Date.now() / 1000);
}

function ttlEpochFor(expiresAt: string): number {
  return Math.floor(new Date(expiresAt).getTime() / 1000);
}

function itemToRecord(item: Record<string, any>): ApprovalRecord {
  return {
    fingerprintHash: item.fingerprintHash,
    summary: item.summary ?? "",
    fingerprintJson: item.fingerprintJson ?? "",
    tool: item.tool,
    ownerSub: item.ownerSub,
    ownerEmail: item.ownerEmail ?? null,
    projectRoot: item.projectRoot,
    grantedAt: item.grantedAt,
    lastUsedAt: item.lastUsedAt,
    useCount: item.useCount ?? 0,
    expiresAt: item.expiresAt,
    intentSnapshot: item.intentSnapshot ?? "",
    goalEmbedding: Array.isArray(item.goalEmbedding) ? item.goalEmbedding : [],
    inputEmbedding: Array.isArray(item.inputEmbedding) ? item.inputEmbedding : [],
    revokedAt: item.revokedAt ?? null,
    revokedBy: item.revokedBy ?? null,
  };
}

export class DynamoApprovalStore implements ApprovalStore {
  private readonly tableName: string;
  private readonly client: DynamoDBDocumentClient;

  constructor(opts: DynamoApprovalStoreOptions) {
    this.tableName = opts.tableName;
    this.client =
      opts.client ??
      DynamoDBDocumentClient.from(new DynamoDBClient({ region: opts.region }), {
        marshallOptions: {
          removeUndefinedValues: true,
          convertClassInstanceToMap: false,
        },
      });
  }

  async recordApproval(input: RecordApprovalInput): Promise<ApprovalRecord> {
    const now = new Date();
    const grantedAt = now.toISOString();
    const expiresAt = new Date(now.getTime() + APPROVAL_TTL_MS).toISOString();
    const ttl = ttlEpochFor(expiresAt);

    // Idempotent upsert: if a record already exists (same scope +
    // fingerprint), refresh lastUsedAt/expiresAt/ttl, bump useCount,
    // restore GSI keys (in case it was revoked and re-granted).
    // ConditionExpression isn't used here — re-granting an actively
    // revoked approval should re-activate it.
    await this.client.send(
      new UpdateCommand({
        TableName: this.tableName,
        Key: { pk: pk(input.scope), sk: sk(input.fingerprintHash) },
        UpdateExpression:
          "SET ownerSub = :os, ownerEmail = :oe, projectRoot = :pr, " +
          "tool = :tool, fingerprintHash = :fh, fingerprintJson = :fj, " +
          "summary = :sum, " +
          "lastUsedAt = :now, expiresAt = :exp, #ttl = :ttl, " +
          "intentSnapshot = :is, goalEmbedding = :ge, inputEmbedding = :ie, " +
          "gsi1pk = :gpk, gsi1sk = :gsk, " +
          "useCount = if_not_exists(useCount, :zero) + :one, " +
          "grantedAt = if_not_exists(grantedAt, :now) " +
          "REMOVE revokedAt, revokedBy",
        ExpressionAttributeNames: { "#ttl": "ttl" },
        ExpressionAttributeValues: {
          ":os": input.scope.ownerSub,
          ":oe": input.ownerEmail,
          ":pr": input.scope.projectRoot,
          ":tool": input.tool,
          ":fh": input.fingerprintHash,
          ":fj": input.fingerprintJson,
          ":sum": input.summary,
          ":now": grantedAt,
          ":exp": expiresAt,
          ":ttl": ttl,
          ":is": input.intentSnapshot,
          ":ge": input.goalEmbedding,
          ":ie": input.inputEmbedding ?? [],
          ":gpk": userGsiPk(input.scope.ownerSub),
          ":gsk": userGsiSk(grantedAt, input.fingerprintHash),
          ":zero": 0,
          ":one": 1,
        },
      }),
    );

    return {
      fingerprintHash: input.fingerprintHash,
      summary: input.summary,
      fingerprintJson: input.fingerprintJson,
      tool: input.tool,
      ownerSub: input.scope.ownerSub,
      ownerEmail: input.ownerEmail,
      projectRoot: input.scope.projectRoot,
      grantedAt,
      lastUsedAt: grantedAt,
      useCount: 1,
      expiresAt,
      intentSnapshot: input.intentSnapshot,
      goalEmbedding: input.goalEmbedding,
      inputEmbedding: input.inputEmbedding ?? [],
      revokedAt: null,
      revokedBy: null,
    };
  }

  async lookup(scope: ApprovalScope, fingerprintHash: string): Promise<ApprovalRecord | null> {
    const r = await this.client.send(
      new GetCommand({
        TableName: this.tableName,
        Key: { pk: pk(scope), sk: sk(fingerprintHash) },
      }),
    );
    if (!r.Item) return null;
    if (r.Item.revokedAt) return null;
    if (new Date(r.Item.expiresAt).getTime() < Date.now()) return null;
    return itemToRecord(r.Item);
  }

  async touchLastUsed(scope: ApprovalScope, fingerprintHash: string): Promise<void> {
    const now = new Date();
    const expiresAt = new Date(now.getTime() + APPROVAL_TTL_MS).toISOString();
    const ttl = ttlEpochFor(expiresAt);
    try {
      await this.client.send(
        new UpdateCommand({
          TableName: this.tableName,
          Key: { pk: pk(scope), sk: sk(fingerprintHash) },
          UpdateExpression:
            "SET lastUsedAt = :now, expiresAt = :exp, #ttl = :ttl, " +
            "useCount = if_not_exists(useCount, :zero) + :one",
          ConditionExpression: "attribute_exists(pk) AND attribute_not_exists(revokedAt)",
          ExpressionAttributeNames: { "#ttl": "ttl" },
          ExpressionAttributeValues: {
            ":now": now.toISOString(),
            ":exp": expiresAt,
            ":ttl": ttl,
            ":zero": 0,
            ":one": 1,
          },
        }),
      );
    } catch (err: any) {
      // Race with revoke / already-expired — silently skip.
      if (err?.name === "ConditionalCheckFailedException") return;
      throw err;
    }
  }

  async listByOwner(ownerSub: string, limit = 200): Promise<ApprovalRecord[]> {
    const r = await this.client.send(
      new QueryCommand({
        TableName: this.tableName,
        IndexName: GSI_NAME,
        KeyConditionExpression: "gsi1pk = :pk",
        ExpressionAttributeValues: { ":pk": userGsiPk(ownerSub) },
        ScanIndexForward: false,
        Limit: limit,
      }),
    );
    return (r.Items ?? []).map(itemToRecord);
  }

  async listAll(limit = 500): Promise<ApprovalRecord[]> {
