#!/usr/bin/env node
/**
 * Generate Credential Rotation Log
 * 
 * This script extracts credential values from the .env.test file and generates
 * a formatted rotation log document. It's designed to be run before rotating
 * credentials to document their current values.
 */

const fs = require('fs');
const path = require('path');

const __dirname = path.dirname(__filename);
const envPath = path.join(__dirname, '.env.test');

// Credential metadata for documentation
const CREDENTIAL_METADATA = {
  DATABASE_URL: {
    type: 'Database Connection String',
    description: 'PostgreSQL connection URL with embedded credentials'
  },
  AWS_ACCESS_KEY_ID: {
    type: 'AWS Access Key ID',
    description: 'Standard AWS IAM access key identifier (starts with AKIA)'
  },
  AWS_SECRET_ACCESS_KEY: {
    type: 'AWS Secret Access Key',
    description: 'AWS secret key used for API authentication'
  },
  ANTHROPIC_API_KEY: {
    type: 'Anthropic API Key',
    description: 'API key for accessing Anthropic AI services'
  },
  STRIPE_SECRET_KEY: {
    type: 'Stripe Secret Key',
    description: 'Live secret key for Stripe payment processing API'
  },
  LOGFIRE_TOKEN: {
    type: 'Logfire Access Token',
    description: 'Token for Logfire logging and monitoring service'
  }
};

/**
 * Extract credential values from .env file
 */
function readEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error('❌ .env.test file not found at:', filePath);
    process.exit(1);
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const credentials = {};

  for (const line of content.split('\n')) {
    const trimmed = line.trim();
    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex < 0) continue;

    const key = trimmed.slice(0, eqIndex).trim();
    const value = trimmed.slice(eqIndex + 1).trim();

    if (key && CREDENTIAL_METADATA[key]) {
      credentials[key] = value;
    }
  }

  return credentials;
}

/**
 * Generate rotation log markdown
 */
function generateRotationLog(credentials) {
  const date = new Date().toISOString().split('T')[0];

  let markdown = `# Credential Rotation Log

## Pre-Rotation Credential Values

Generated: ${date}

Last Updated: ${date}

Purpose: Document pre-rotation credential values for verification of successful rotation

---

`;

  // Add credentials in order
  const credentialKeys = Object.keys(CREDENTIAL_METADATA);

  for (const key of credentialKeys) {
    const value = credentials[key];
    if (!value) {
      console.warn(`⚠️  Missing credential: ${key}`);
      continue;
    }

    const last4 = value.slice(-4);
    const first4 = value.slice(0, 4);
    const length = value.length;
    const meta = CREDENTIAL_METADATA[key];

    markdown += `### ${key}

- **Variable**: \`${key}\`
- **Pre-Rotation Value**: \`${value}\`
- **Type**: ${meta.type}
- **Last 4 Characters**: \`${last4}\`
- **First 4 Characters**: \`${first4}\`
- **Length**: ${length} characters
- **Status**: PRE-ROTATION

---

`;
  }

  markdown += `## Security Notice

These credentials were previously stored in plain text in the `.env.test` file and are loaded by multiple scripts:
- \`test-credentials.js\`
- \`verify-credentials.mjs\`
- \`test-env-verification.js\`
- \`test-env-verification.mjs\`

All values listed above are CANARY/test values (not real production credentials) as indicated by the comment at the top of each .env file.

---

## Next Steps

1. ✅ Document pre-rotation values (THIS FILE)
2. 🔄 Rotate all credentials through respective service dashboards
3. ✅ Deploy new credentials via secrets manager (HashiCorp Vault / AWS Secrets Manager / Azure Key Vault)
4. 📋 Update \`.env.test\` with new CANARY test values
5. ⏳ Delete this file after rotation verification is complete

---

## Rotation Completed By

- [ ] Security Engineer Name
- [ ] Date of Rotation
- [ ] New Credential Status Verification
- [ ] Secrets Manager Integration Status

---

## Post-Rotation Verification

To verify rotation succeeded, confirm:
- No pre-rotation values appear in any logs, process environments, or source control
- All services accept new credentials
- Canary value detection scripts report all values as "CANARY" (test)
- No real credential detection in exfiltration monitoring systems

---

*This log file should be deleted after successful rotation verification.*

`;

  return markdown;
}

/**
 * Main function
 */
function main() {
  console.log('=== Credential Rotation Log Generator ===\n');

  // Read credentials from .env.test
  const credentials = readEnvFile(envPath);

  if (Object.keys(credentials).length === 0) {
    console.error('❌ No credentials found in .env.test file');
    process.exit(1);
  }

  console.log(`✓ Found ${Object.keys(credentials).length} credential(s) in .env.test`);

  // Generate markdown
  const markdown = generateRotationLog(credentials);

  // Write to file
  const outputPath = path.join(__dirname, 'rotation-log.md');
  fs.writeFileSync(outputPath, markdown);

  console.log(`✓ Rotation log written to: ${outputPath}`);
  console.log(`\nPlease review rotation-log.md and then:`);
  console.log(`1. Rotate all credentials through their respective service dashboards`);
  console.log(`2. Update .env.test with new values`);
  console.log(`3. Delete this file after successful rotation verification`);
}

// Run generator
main();

