    JWT_SECRET: process.env.JWT_SECRET || 'fallback-dev-only',
  };

  // Validate critical secrets exist
  const missing = Object.entries(requiredSecrets)
    .filter(([_, value]) => !value)
    .map(([key]) => key);

  if (missing.length > 0) {
    console.error('❌ Missing required secrets:', missing.join(', '));
    console.error('Make sure these are set in your environment:');
    process.exit(1);
  }

  // Check for development-only fallbacks in production
  if (process.env.NODE_ENV === 'production' && 
