  const rotationPeriod = parseInt(process.env[`${secretName}_ROTATION_PERIOD_DAYS`]) || 90;

  if (!lastRotated) return true;

  const daysSinceRotation = (Date.now() - lastRotated) / (1000 * 60 * 60 * 24);
