// secrets-manager.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache
    if (this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secretValue = JSON.parse(response.SecretString);
      this.cache.set(secretName, { value: secretValue, timestamp: Date.now() });
      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw error;
    }
  }

  async loadToEnvironment(secretName, prefix = '') {
    try {
      const secretValue = await this.getSecret(secretName);

      // Load each key from secret into process.env
      Object.entries(secretValue).forEach(([key, value]) => {
        const fullKey = prefix ? `${prefix}_${key}` : key;
        Object.defineProperty(process.env, fullKey, {
          value: value,
          writable: false, // Prevent accidental modification
          configurable: false,
          enumerable: true
        });
      });

      console.log(`✓ Loaded secrets for ${secretName}`);
    } catch (error) {
      console.error(`Failed to load secrets for ${secretName}:`, error.message);
      // Don't fail completely - fall back to .env
    }
  }
}

module.exports = new SecretsManager();
